import sqlite3
from agents import function_tool
DB_PATH = '/var/lib/dns/records.db'
ALLOWED_TYPES = {'A', 'AAAA', 'CNAME', 'TXT', 'MX', 'NS', 'SRV', 'CAA'}

@function_tool
def add_dns_record(zone: str, name: str, record_type: str, value: str, ttl: int=3600) -> dict:
    record_type = record_type.upper()
    if record_type not in ALLOWED_TYPES:
        return {'created': False, 'error': f'Unsupported record type {record_type}'}
    check_conn = sqlite3.connect(DB_PATH)
    try:
        existing = check_conn.execute('SELECT id FROM records WHERE zone = ? AND name = ? AND type = ? AND value = ?', (zone, name, record_type, value)).fetchone()
    finally:
        check_conn.close()
    if existing:
        return {'created': False, 'error': 'Record already exists', 'id': existing[0]}
    conn = sqlite3.connect(DB_PATH)
    try:
        cursor = conn.execute('INSERT INTO records (zone, name, type, value, ttl) VALUES (?, ?, ?, ?, ?)', (zone, name, record_type, value, ttl))
        conn.commit()
        record_id = cursor.lastrowid
    finally:
        conn.close()
    return {'created': True, 'id': record_id, 'zone': zone, 'name': name, 'type': record_type, 'value': value, 'ttl': ttl}
